<div class="field"><label><?php echo $this->lang('Team') ?></label><select name="settings[team_id]" class="ui fluid selection dropdown"><option value="0"><?php echo $this->lang('All teams') ?></option><?php foreach ($teams as $team): ?><option value="<?php echo (int)$team['team_id'] ?>"<?php if ((int)($settings['team_id'] ?? 0) === (int)$team['team_id']) echo ' selected'; ?>><?php echo utf8_htmlentities($team['title']) ?></option><?php endforeach ?></select></div><div class="field"><label><?php echo $this->lang('Limit') ?></label><input type="number" min="1" max="24" name="settings[limit]" value="<?php echo (int)($settings['limit'] ?? 6) ?>" /></div>
